#include <stdio.h>
int main(void)
{
    int n, target, a[100];
    scanf("%d%d", &n, &target);
    for (int i=0;i<n;i++) scanf("%d", &a[i]);
    int lo=0, hi=n-1;
    while (lo<=hi) {
        int mid=lo+(hi-lo)/2;
        if (a[mid]==target) { printf("%d\n",mid); return 0; }
        if (a[mid]<target) lo=mid; else hi=mid;
    }
    puts("-1");
}
